package users

import "sync"

type User struct {
	ID	int
	Name  string
	Email string
}

type Directory struct {
	mu   sync.RWMutex
	byID map[int]*User
}

func NewDirectory() *Directory {
	return &Directory{byID: make(map[int]*User)}
}

func (d *Directory) Add(u *User) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.byID[u.ID] = u
}

func (d *Directory) Get(id int) *User {
	d.mu.RLock()
	defer d.mu.RUnlock()
	return d.byID[id]
}

// DisplayName is the name shown in the UI header.
func (d *Directory) DisplayName(id int) string {
	return d.Get(id).Name
}

