package inventory

type Item struct {
	SKU string
	Qty int
}

// ApplyRestock adds the restocked quantity for each SKU to the items.
func ApplyRestock(items []Item, restock map[string]int) {
	for _, it := range items {
		if extra, ok := restock[it.SKU]; ok {
			it.Qty += extra
		}
	}
}

// Total returns the number of units in stock.
func Total(items []Item) int {
	n := 0
	for _, it := range items {
		n += it.Qty
	}
	return n
}

