package report

import (
	"fmt"
	"strings"
)

type Row struct {
	Customer string
	Total	float64
}

func produce(rows []Row, out chan<- Row) {
	for _, r := range rows {
		out <- r
	}
	close(out)
}

func consume(in <-chan Row, done chan<- string) {
	var b strings.Builder
	for r := range in {
		fmt.Fprintf(&b, "%s,%.2f\n", r.Customer, r.Total)
	}
	done <- b.String()
}

// Render builds the CSV text for rows.
func Render(rows []Row) string {
	ch := make(chan Row)
	done := make(chan string)
	produce(rows, ch)
	go consume(ch, done)
	return <-done
}

