// WithAudit returns the steps with an audit step inserted before the last step.
func WithAudit(steps []string) []string {
	head := steps[:len(steps)-1]
	return append(head, "audit", steps[len(steps)-1])
}

func Describe(steps []string) string {
	return strings.Join(steps, " -> ")
}

