package docs

import (
	"context"
	"errors"
	"log"
)

type Doc struct {
	ID   string
	Body string
}

func (d Doc) Valid() bool { return d.ID != "" && d.Body != "" }

type Store interface {
	Put(ctx context.Context, d Doc) error
}

type Service struct {
	store Store
}

// Save stores a valid document and reports whether it succeeded.
func (s *Service) Save(ctx context.Context, d Doc) error {
	var err error
	if d.Valid() {
		err := s.store.Put(ctx, d)
		if err != nil {
			log.Printf("docs: put %s failed: %v", d.ID, err)
		}
	} else {
		err = errors.New("docs: invalid document")
	}
	return err
}

