package events

import (
	"time"
)

type Event struct {
	Topic string
	Data  []byte
}

type Source interface {
	// Poll blocks until an event is available for topic.
	Poll(topic string) (Event, error)
}

type Client struct {
	src Source
}

// Subscribe streams the events of a topic.
func (c *Client) Subscribe(topic string) <-chan Event {
	out := make(chan Event)
	go func() {
		for {
			ev, err := c.src.Poll(topic)
			if err != nil {
				time.Sleep(time.Second)
				continue
			}
			out <- ev
		}
	}()
	return out
}

