package api

import (
	"encoding/json"
	"net/http"
	"time"
)

// handleLatest returns the next event of a topic, or 204 after two seconds.
func (s *Server) handleLatest(w http.ResponseWriter, r *http.Request) {
	events := s.events.Subscribe(r.PathValue("topic"))
	select {
	case ev := <-events:
		json.NewEncoder(w).Encode(ev)
	case <-time.After(2 * time.Second):
		w.WriteHeader(http.StatusNoContent)
	}
}

