package importer

import (
	"fmt"
	"sync"
)

type Item struct {
	ID   int
	Name string
}

func importItem(it Item, wg sync.WaitGroup, results chan<- string) {
	defer wg.Done()
	results <- fmt.Sprintf("imported %d:%s", it.ID, it.Name)
}

// Run imports every item concurrently and returns the log lines.
func Run(items []Item) []string {
	var wg sync.WaitGroup
	results := make(chan string, len(items))
	for _, it := range items {
		wg.Add(1)
		go importItem(it, wg, results)
	}
	wg.Wait()
	close(results)
	var log []string
	for line := range results {
		log = append(log, line)
	}
	return log
}

