import (
	"fmt"
	"sync"
)

// Stats counts cache hits and misses. It is safe for concurrent use.
type Stats struct {
	mu	 sync.Mutex
	hits   int
	misses int
}

func (s *Stats) Hit() {
	s.mu.Lock()
	s.hits++
	s.mu.Unlock()
}

func (s *Stats) Miss() {
	s.mu.Lock()
	s.misses++
	s.mu.Unlock()
}

func (s Stats) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return fmt.Sprintf("hits=%d misses=%d", s.hits, s.misses)
}

