from typing import Callable


class Registry:
    def __init__(self) -> None:
        self.handlers: dict[str, Callable[[], str]] = {}

    def register(self, name: str, handler: Callable[[], str]) -> None:
        if name in self.handlers:
            raise ValueError(f"plugin {name!r} is already registered")
        self.handlers[name] = handler

    def unregister(self, name: str) -> None:
        self.handlers.pop(name, None)

    def names(self) -> list[str]:
        return sorted(self.handlers)

    def run(self, name: str) -> str:
        return self.handlers[name]()


def build_registry(names: list[str]) -> Registry:
    registry = Registry()
    for name in names:
        registry.register(name, lambda: f"hello from {name}")
    return registry

