from collections.abc import Iterable, Iterator
from decimal import Decimal


def read_invoices(rows: Iterable[dict]) -> Iterator[dict]:
    for row in rows:
        if row["status"] != "void":
            yield {"customer": row["customer"], "amount": Decimal(row["amount"])}


def build_report(rows: Iterable[dict]) -> dict:
    invoices = read_invoices(rows)
    count = sum(1 for _ in invoices)
    total = sum((inv["amount"] for inv in invoices), Decimal("0"))
    by_customer: dict[str, Decimal] = {}
    for inv in invoices:
        by_customer[inv["customer"]] = by_customer.get(inv["customer"], Decimal("0")) + inv["amount"]
    return {"count": count, "total": total, "by_customer": by_customer}

