import functools
from pathlib import Path

from PIL import Image


class Thumbnailer:
    def __init__(self, size: tuple[int, int], cache_dir: Path) -> None:
        self.size = size
        self.cache_dir = cache_dir
        self._font = None

    @functools.lru_cache(maxsize=None)
    def target_path(self, source: str) -> Path:
        name = Path(source).stem
        return self.cache_dir / f"{name}_{self.size[0]}x{self.size[1]}.jpg"

    def render(self, source: str) -> Path:
        target = self.target_path(source)
        if not target.exists():
            with Image.open(source) as img:
                img.thumbnail(self.size)
                img.convert("RGB").save(target, "JPEG", quality=85)
        return target

