export async function loadOrders(search: string) {
  const params = new URLSearchParams(search);
  const ids = parseIds(params.get("ids") ?? "");
  if (ids.length === 0) {
    return [];
  }
  const res = await fetch(buildUrl(ids));
  if (!res.ok) {
    throw new Error(`orders request failed: ${res.status}`);
  }
  return (await res.json()) as { id: number; total: number }[];
}

