import { cartTotal } from "./total";
import type { Line } from "./total";
import { gateway } from "../gateway";

export async function pay(lines: Line[], token: string) {
  const total = cartTotal(lines);
  const quote = await gateway.quote(token); // { amount: 0.3 } for these lines
  if (total !== quote.amount) {
    throw new Error(`Amount mismatch: computed ${total}, gateway ${quote.amount}`);
  }
  return gateway.charge(token, total);
}

