import { fetchRows, Filters, Row } from "./api";

export function Results({ filters }: { filters: Filters }) {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(false);

  const options = { ...filters, limit: 20, sort: "recent" };

  useEffect(() => {
    setLoading(true);
    fetchRows(options)
      .then((data) => setRows(data))
      .finally(() => setLoading(false));
  }, [options]);

  return (
    <section aria-busy={loading}>
      {rows.map((row) => (
        <article key={row.id}>{row.title}</article>
      ))}
    </section>
  );
}

